        "text": "Тот [Свет], что пребывает между двух [начал], подобный вспышке молнии или языку пламени, от одного лишь присутствия которого сияет [весь] мир, — та высшая, состоящая из чистого сознания Реальность (Брахман) раскрывается лишь для немногих — для тех, у кого накоплен великий запас благих заслуг (пунья)."
