        "text": "Вайкранта продлевает жизнь, укрепляет силу и цвет кожи, даёт великую храбрость, наделяет мудростью, устраняет все доши и болезни, разжигает пищеварительный огонь, обладает свойствами, равными алмазу, и делает тело крепким, как алмазно-твёрдый металл."
