        "sanskrit": "इरिद्रा-तिफला-रल-सिन्ु-घूमे' सटङलेः । सारुष्करेइच पाटागैः सासः सम्मदं सर्प॑रम्‌ ॥ १५० ॥ लिप ठन्ताकमनूषाया शोषयिल्ला निरुध्य च । मूषा मूपोपरि न्यस्य खपर प्रधमेतततः ॥ १५१॥ खपरे प्रदूते ज्वाला भवेन्नोला मिता यदि । तटा मन्दशतो मूषां टता कत्वा लधोसुखोम्‌ ॥ १५२॥ शनेरास्फलयदमौ यथा नाल न मज्यते। वङ्गाभ पतित स्वं समाटाय नियोजयेत्‌ ॥ एव तिचतुरैर्गारे. सवं सच्च विनि'सरेत्‌ ॥ १५३ ॥",
        "text": "Расаку тщательно растирают с куркумой, трифалой, каменной солью, сажей, бурой, марьяльным орехом и корнем патхи; обмазывают тигель, высушивают и запечатывают; плавят расаку раздуванием огня. Когда пламя станет синеватым, тигель снимают, переворачивают и выпускают вытекшую сущность, похожую на олово."
