        "sanskrit": "यदा जलयुता खालों निखनेत्‌ कोष्िको दरे । सच्छिद्रं तन्मुखे मन्न त्ब खेऽधोसुखौं चिपेत्‌ ॥ १५७ ॥ द्रूषोयर शिखिताञ्च प्रक्तिष्य प्रघसेद््‌टम्‌। पतित स्थालिकानोरे सचछमादाय योजयेत्‌ ॥ १५८ ॥",
        "text": "Сосуд с водой закапывают у входа в печь; сверху устанавливают перевёрнутый сосуд с отверстием; куски расаки нагревают огнём сверху; расплавленное вещество стекает через отверстие в нижний сосуд, откуда полученную сущность собирают."
