        "text": "Для использования в алхимии ртути (расе), в расаяне (омолаживающих средствах), при дарении, ношении и в почитании божеств рекомендованы драгоценные камни хороших признаков и лучшего происхождения — только такие ведут к успеху (сиддхи)."
