        "text": "Соком, выжатым из плодов мадана (растения-эметика), растирают «бхунагаку» (растение), обмазывают этой пастой алмаз и двадцать раз прокаливают в горне — тогда алмаз становится «нетленным» (пригодным, устойчивым) и может применяться в препаратах на основе ртути и других (алхимических средствах)."
