        "sanskrit": "अष्टादशभुजं शुभ्रं पूर्वोक्तं त्रिलोचनम्। वृषभारूढं नीलकण्ठं रसलिङ्गं विचिन्तयेत्॥",
        "text": "[В медитации-дхьяне] следует созерцать расалингу как [божество] с восемнадцатью руками, светозарное, ранее описанное, трёхокое, восседающее на быке, синегорлое (Нилакантха — эпитет Шивы)."
