        "type": "verse",
        "number": "48",
        "sanskrit": "[पूर्वे स्वर्णं दक्षिणे ताम्रं] पश्चिमे वङ्गं कान्तौ च उत्तरे [मुण्डतौ] एके। [एवमेव तद्दिशोरेव] पूजयेदर्घ्यान्वितम्॥",
        "text": "[Стих сильно повреждён, восстановление предположительно.] Смысл, по-видимому, таков: на востоке [полагается золото], на юге медь, на западе — олово и магнитный камень, на севере — свинец (или одно из перечисленного); каждый металл следует почтить в соответствующем направлении подношением воды (аргхья)."
