        "type": "verse",
        "number": "51",
        "sanskrit": "द्रव्यौषधीनां वर्गश्च रञ्जकश्छेदनानि च। [...] विविधानि च। एतानि द्वारवाह्ये तु मूलमन्त्रेण पूजयेत्॥",
        "text": "Набор веществ и трав, красители, режущие орудия и прочее разнообразное — всё это, [размещённое] снаружи у двери, следует почтить коренной мантрой (мула-мантра)."
