        "text": "[Названия ряда ингредиентов («вришья», «сугандха» и др.) отождествлены по комментарию лишь предположительно.] Ртуть, сера, медь(-бхасма), лангали (Gloriosa superba), вахни (читрака), рамата (асафетида), «вришья» (видья — видья?), патола, ниргунди, «сугандха» (расна) и листья нимбы —"
