        "text": "[Точный состав «кшаратраи» — трёх щелочей — и часть прочих названий остаются неуверенными.] Патха, три вида кшары (щёлочи), бол (гуггул/мирра) вместе с красным рисом, старая патока (гуда) и экстракт солодки (мадхукасара) — всё это растирают с соком лимона (нимбу)."
