        "text": "Из этого делают пилюли весом в один нишку; такая пилюля, называемая «Саннипата-гаджанкуша» («слоновий стрекало для саннипаты»), сдерживает [чрезмерное] потоотделение, жжение и абхинъясу (кризисную стадию, помрачение сознания) при саннипате."
