        "text": "[Название формулы — «Амритарнава» — реконструировано по сильно повреждённому фрагменту с невысокой степенью уверенности; возможны и другие прочтения.] Тапья (свернамакшика), таллак (аурипигмент), джайпала (семя кротона), вачанабха (аконит), манахшила — вместе с медью и серой, растёртые ртутью, — обжигаются в «куккута-путе» (лёгком, «куриного» жара обжиге); [полученное средство] известно как «Амритарнава»."
