        "text": "[Название болезни реконструировано как «раджаякшма», но с неполной уверенностью.] [Это средство] устраняет кушу (кожные болезни), панду (малокровие), раджаякшму, камалу (желтуху) и болезни капхи. Как насья — семя гирикарники (апараджиты) одно, растёртое холодной водой."
