        "number": "127",
        "sanskrit": "रसस्य परमा मात्रा चाङ्गुल्या परिकीर्तिता। काचकूप्यां निक्षिप्य यन्त्रे क्षिप्त्वा प्रयत्नवान् ॥१२७॥",
        "text": "[Слово «чангульи» как единица меры вызывает сомнения.] Наибольшая мера этого раса указана определённым образом; заботливо поместив [состав] в стеклянный сосуд, ставят его в [нагревательный] аппарат."
