        "sanskrit": "उत्थाप्याद्रकनिर्यासैर्मर्दयित्वा विशोषयेत्। संजीवनाख्यो नाम्ना रसोऽयं विदितो भुवि। गुञ्जाह्वयं ददतोऽस्य सन्निपातापनुत्तये ॥१२८॥",
        "text": "Извлекши [из аппарата], растирают соком имбиря и высушивают. Этот раса известен на земле под именем «Сандживана»; принимаемый в дозе, равной семени гунджи, он устраняет саннипату."
