        "text": "Раздел «Мулакутхара» (топор, разящий геморрой в корне). Известный [под названием, не поддающимся уверенному отождествлению] ингредиент «варанама», а также очищенная слюда (абхрака-саттва), медь и железо — всё это вместе расплавляют, постепенно понемногу помешивая. Непрерывно помешивают, добавляя аурипигмент (харитала) в двойной доле; растирая это с ртутью, изготавливают пасту. Затем эту пасту постепенно помещают внутрь корня дерева бхаллатака, а после — в коровье молоко. Затем, извлекая масло плодов бхаллатаки методом нисходящей перегонки («паталаянтра»), помещают ту пасту в промасленный железный сосуд. Ежедневно с большим тщанием обновляют это масло; пропитанное маслом и серой вещество после многократного прокаливания (пута) превращается в золу (бхасма). Затем в месяце Картика [деталь стиха 37 повреждена] это вещество растирают, выставляют на солнце и прокаливают повторно. Полученную золу смешивают в равной доле с прежней золой; добавляют дикий сурана, ниргунди, «канда» (mahārāṣṭrī) и бхринга с колючим растением (кантика). Растирают их соками и высушивают; дважды растворяют соком арки (Calotropis) и снова высушивают; тщательно измельчив в порошок, закладывают в короб. Этот превосходный раса, называемый «Мулакутхара», подобен разгорающемуся пищеварительному огню (Вайшванаре); принимаемый должным образом, он уничтожает тяжёлые заболевания геморроидального рода, острейшие боли, связанные с прямой кишкой, расстройство удана-ваю, нарушение грахани (кишечного пищеварения), гульму, болезни печени, ослабление пищеварения и кожные заболевания (кушта). [Стих сильно повреждён OCR на стыке двух страниц источника; часть слов, особенно в начале второй половины (стих 40), восстановлена предположительно.]"
