        "text": "Раздел [название формулы не читается уверенно, по составу — каджали-подобный препарат]. Свинец, ртуть, серу, три вида соли и «вайавья» (ветрогонный порошок) соединяют — каждого по одной пале, а прочих [ингредиентов] — по три палы каждого, добавляя по порядку. Всё это в тот же день обрабатывают, затем прокаливают в горне; проводят двадцать пять обработок (бхавана) соком семи плодов и ещё одним компонентом [не отождествлён уверенно]. Пять раз, последовательно, обрабатывают в патоковой воде; растение вāлли (плющевидное) в воде разрушает слизистые скопления; сурана в составе этого средства полезна для питания [больного]. «Пусть избегают арки (Calotropis)», — так сказал мудрец Саувасудева (Шри Васудева); также следует избегать тыквы, [некоторых] плодов, урада (чёрного гороха), молочной каши, чрезмерных физических упражнений и долгого пребывания на солнце. [Ряд деталей приготовления в стихе 62 сильно повреждён OCR.]"
