        "text": "Раздел «Тикшна-мукха-раса» (второй). «Индра-хемакша», «видала-гола», «сурайаса» (виды железной руды), окалина железа, слюда и сера, а также тапья (пирит/слюда), растёртые на соке алоэ, после варки и прокаливания образуют «Тикшна-мукху» — средство от геморроя. [Названия минеральных компонентов сильно специфичны и не поддаются полностью уверенному отождествлению из-за повреждения OCR.]"
