        "text": "Раздел «Аршах-кутхара» (второй). [Начало стиха сильно повреждено — упомянуты некий острый ингредиент и уваренное касторовое масло.] В мере молока (прастха) с ложкой ртути — пала, серы — пала; меди — три палы, кудава железа, а также пять частей щёлочи (раджах-кшара) — всё это, брошенное в ступку, варят; полученный состав, пылающий подобно огню, называется «Аршах-кутхара». [Точные пропорции и ряд названий ингредиентов в этом стихе не поддаются уверенной реконструкции из-за сильного повреждения OCR.]"
