        "text": "Раздел «Аршахара-йога» (пищевое средство против геморроя). Нежные листья кусумбхи (сафлора) варят на канджике (кислом рисовом отваре); съедают их ежедневно как овощное блюдо для успокоения геморроидальной болезни."
