        "text": "[Стих сильно повреждён OCR, дословную санскритскую форму восстановить с полной уверенностью не удалось; перевод даётся по общему смыслу, подтверждаемому комментарием.] Когда нисходящий по природе ветер (вата) оказывается перекрыт — из-за подавления позывов к мочеиспусканию, дефекации и иных естественных нужд, — он временами пересушивает кал на своём пути и приобретает извращённое, обратное движение. Двигаясь так, он вызывает боль в области сердца, спины, живота, мочевого пузыря и головы, а также одышку, кашель и лихорадку; постоянно порождаемый гневом и подавлением побуждений, он именно так вызывает адховату (нарушение нисходящего движения ветра) и удаварту (болезнь его обратного, восходящего хода)."
