        "text": "[Раздел «Вадавамукха-гутика» — пилюли «Пасть подводного огня»]. Зола железа (лоуха-бхасма) с рядом иных компонентов (специи, листья нимбы и др.; часть названий повреждена OCR и не поддаётся надёжному восстановлению), соединённая с куркумой и солью, растёртая вместе с ядом (виша), тиндукой и иным соком, скреплённая топлёным маслом до густоты гуджи (мёда), — так изготовляется гутика «Вадавамукха», дающая необычайно сильный пищеварительный жар."
