        "text": "Полученный состав принимают ежедневно вместе с соком (кашицей) листьев бетеля. Эта раса-йога (лекарственный состав на основе ртути) известна как устраняющая ватагулму (опухолевидное вздутие живота, вызванное расстройством Ваты) и носит название «Шикхивадава»."
