        "text": "Видангу (плоды Embelia ribes), кожуру граната, каменную соль, кардамон и соль сувarchala растирают на соке цитрона (матулунга) — один из компонентов в этом месте текста сильно повреждён OCR и не поддаётся уверенному восстановлению — и принимают вместе с вином (сурой). Это приятная анупана (сопутствующее средство), также устраняющая ватагулму."
